import sys

def classify_grade(score):
    if score >= 90 and score <= 100:
        return "Excellent"
    elif score >= 75 and score <= 89:
        return "Good"
    elif score >= 50 and score <= 74:
        return "Average"
    elif score >= 35 and score <= 49:
        return "Pass"
    elif score >= 0 and score <= 34:
        return "Fail"
    return None

def main():
    lines = sys.stdin.read().strip().split('\n')
    idx = 0

    while idx < len(lines):
        line = lines[idx].strip()
        if not line:
            idx += 1
            continue

        n = int(line)
        idx += 1

        if idx >= len(lines):
            break

        scores_line = lines[idx].strip()
        idx += 1

        scores = list(map(int, scores_line.split()))

        for score in scores:
            if score == -1:
                break
            classification = classify_grade(score)
            if classification:
                print(classification)

if __name__ == "__main__":
    main()
